        ans += minSum[0];
        segment.length = 0; // 开始记录新的分段
      }
    } else {
      segment.push(diff); // 如果diff不大于d，那么说明 i - 1 可以和 i 组队匹配，此时将实力差（相当于一个组队匹配）计入分段
